        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

